/// <summary>
///  Triggers the <c>METDMFDataVizualizationFormEventHandler</c> class to export staging error log to excel.
/// </summary>
/// <param name="sender">The form button</param>
/// <param name="e">Ther event args</param>
[FormControlEventHandler(formControlStr(DMFDataVizualization, METDownloadLog), FormControlEventType::Clicked),
     SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void METDownloadLog_OnClicked(FormControl sender, FormControlEventArgs e)
{
    DMFDefinitionGroupExecution defGroupExecutionTable = sender.formRun().args().record();
    DMFEntity                   dmfEntity;

    if (defGroupExecutionTable)
    {
        dmfEntity = DMFEntity::find(defGroupExecutionTable.Entity);
        if (!dmfEntity)
        {
            throw error(strFmt("@MET:EntityMissing", defGroupExecutionTable.ExecutionId));
        }
        METDMFDownloadErrorLog  downloadErrorLog = METDMFDownloadErrorLog::construct(defGroupExecutionTable.ExecutionId, dmfEntity.EntityTable);
        downloadErrorLog.logStagingError();
    }
}
